/* Service worker: precaches the whole app (shell + all data) for offline use. Generated by tools/build_sw.py */
var CACHE = "kjvsb-4518a1200d";
var FILES = [
  "./",
  "./css/app.css",
  "./data/kjv.json",
  "./data/luther.json",
  "./data/study.json",
  "./data/xref.json",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-32.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/maskable-512.png",
  "./index.html",
  "./js/app.js",
  "./js/books.js",
  "./js/search-worker.js",
  "./manifest.webmanifest"
];
self.addEventListener("install", function(e){
  e.waitUntil(caches.open(CACHE).then(function(c){ return c.addAll(FILES.map(function(f){ return new Request(f, {cache:"reload"}); })); }).then(function(){ return self.skipWaiting(); }));
});
self.addEventListener("activate", function(e){
  e.waitUntil(caches.keys().then(function(keys){
    return Promise.all(keys.filter(function(k){ return k.indexOf("kjvsb-")===0 && k!==CACHE; }).map(function(k){ return caches.delete(k); }));
  }).then(function(){ return self.clients.claim(); }));
});
self.addEventListener("fetch", function(e){
  var req = e.request;
  if(req.method!=="GET") return;
  var url = new URL(req.url);
  if(url.origin!==self.location.origin) return;
  e.respondWith(caches.open(CACHE).then(function(c){
    return c.match(req, {ignoreSearch:true}).then(function(hit){
      if(hit) return hit;
      if(req.mode==="navigate") return c.match("./index.html").then(function(r){ return r || fetch(req); });
      return fetch(req);
    });
  }));
});
